def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_values = [row[i] for row in rows]
        total = 0
        numeric = True
        for val in col_values:
            try:
                f = float(val)
                total += f
            except (TypeError, ValueError):
                numeric = False
                break
        if numeric:
            totals.append(total)
        else:
            totals.append("")
    return totals

